+    if (statx(fd, "", AT_EMPTY_PATH, STATX_DIOALIGN, &stx) == 0 &&
+        (stx.stx_mask & STATX_DIOALIGN) && stx.stx_dio_mem_align > 0) {
+        alignment = stx.stx_dio_mem_align;
+    }
+#endif
+    return alignment;
+}
